css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .texto-box{border: 2px solid var(--bosque); border-radius: 12px; padding: 10px 12px; margin-bottom: 10px; width: 100%;}
.mz .texto-parrafo{font-size: 16px; font-weight: 600; line-height: 1.55;}
.mz .preguntas-lista{display: flex; flex-direction: column; gap: 7px; margin-bottom: 10px;}
.mz .pregunta-item{display: flex; flex-direction: column; gap: 2px;}
.mz .pregunta-texto{font-size: 15px; font-weight: 700;}
.mz .respuesta-linea{border-bottom: 1.5px solid var(--bosque); height: 20px; width: 100%;}
.mz .ordenar-lista{display: flex; flex-direction: column; gap: 8px; margin-bottom: 10px;}
.mz .ordenar-item{display: flex; align-items: center; gap: 10px;}
.mz .ordenar-caja{width: 26px; height: 26px; border: 2px solid var(--bosque); flex-shrink: 0; border-radius: 4px;}
.mz .ordenar-texto{font-size: 15px; font-weight: 600; line-height: 1.3;}
.mz .banco{font-family: sans-serif; font-size: 12px; font-weight: 700; background: #f0f0f0; border: 1px solid #ccc; border-radius: 6px; padding: 4px 10px; display: inline-block; margin-bottom: 7px;}
.mz .conectores-lista{display: flex; flex-direction: column; gap: 9px; margin-bottom: 10px;}
.mz .conector-item{display: flex; align-items: flex-end; gap: 6px; flex-wrap: wrap;}
.mz .conector-hueco{border-bottom: 1.5px solid var(--bosque); min-width: 95px; height: 20px; flex-shrink: 0;}
.mz .conector-texto{font-size: 15px; font-weight: 600; line-height: 1.3;}
.mz .escribir-lineas{display: flex; flex-direction: column; gap: 6px; margin-bottom: 8px;}
.mz .escribir-linea{border-bottom: 1.5px solid var(--bosque); height: 22px; width: 100%;}
.mz .txt-flex{flex: 1 1 auto; min-width: 0;}
.mz .texto-parrafo{line-height: 1.725 !important;}
